import { Aes256Gcm, CipherSuite, DhkemX25519HkdfSha256, HkdfSha256 } from '@hpke/core';

// The caller validates its purpose-specific context and envelope. This key is
// generated by its trusted consumer and consumed by the first open attempt.
export async function createVaultDisplayRecipient(
  domain: string,
  fields: string[],
  envelope: (value: unknown) => { enc: Uint8Array; ciphertext: Uint8Array } | undefined,
) {
  const encoder = new TextEncoder();
  const prefix = encoder.encode(domain);
  const requestFields = fields.map((value) => encoder.encode(value));
  let pair: CryptoKeyPair | undefined = (await crypto.subtle.generateKey(
    { name: 'X25519' },
    false,
    ['deriveBits'],
  )) as CryptoKeyPair;
  const publicKey = btoa(
    String.fromCharCode(...new Uint8Array(await crypto.subtle.exportKey('raw', pair.publicKey))),
  );
  const suite = new CipherSuite({
    kem: new DhkemX25519HkdfSha256(),
    kdf: new HkdfSha256(),
    aead: new Aes256Gcm(),
  });
  let disposed = false;
  return {
    publicKey,
    dispose() {
      disposed = true;
      pair = undefined;
    },
    async open(
      value: unknown,
      authenticatedResponseFields: readonly string[] = [],
    ): Promise<Uint8Array> {
      const key = pair;
      pair = undefined;
      if (!key || disposed) throw Error('Display recipient is closed.');
      const bundle = envelope(value);
      if (!bundle) throw Error('Invalid display response.');
      const values = [
        ...requestFields,
        ...authenticatedResponseFields.map((field) => encoder.encode(field)),
      ];
      const info = new Uint8Array(
        prefix.length + values.reduce((sum, field) => sum + 4 + field.length, 0),
      );
      info.set(prefix);
      const view = new DataView(info.buffer);
      let offset = prefix.length;
      for (const field of values) {
        view.setUint32(offset, field.length);
        info.set(field, offset + 4);
        offset += 4 + field.length;
      }
      const bytes = new Uint8Array(
        await suite.open({ recipientKey: key, enc: bundle.enc, info }, bundle.ciphertext),
      );
      if (disposed) {
        bytes.fill(0);
        throw Error('Display recipient is closed.');
      }
      return bytes;
    },
  };
}
